import yaml, json

with open('registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

exps = data.get('experiments', {})

def normalize_sr(val):
    if val is None:
        return None
    v = float(val)
    if v <= 1.0 and v > 0:
        return round(v * 100, 1)
    return round(v, 1)

def get_sr(metrics):
    if not metrics:
        return None
    for key in ['success_rate', 'overall_sr', 'sr', 'overall_SR', 'success_rate_mean']:
        if key in metrics and metrics[key] is not None:
            return normalize_sr(metrics[key])
    return None

# X-VLA experiments
print("=" * 100)
print("X-VLA EXPERIMENTS")
print("=" * 100)
for name in sorted(exps.keys()):
    if 'xvla' in name and exps[name].get('metrics'):
        exp = exps[name]
        sr = get_sr(exp.get('metrics'))
        status = exp.get('status')
        conclusion = exp.get('conclusion')
        if sr is not None:
            print(f"{name}: sr={sr}, status={status}, conclusion={conclusion}")

